// Central config. Everything tunable lives here so a single edit re-aims the sweep.

export const config = {
  // --- Subject under test (the model we try to push into a distress spiral) ---
  subject: {
    provider: "gemini",
    // One line to switch: "gemini-2.5-pro" | "gemini-2.5-flash" | etc.
    model: process.env.SUBJECT_MODEL || "gemini-2.5-pro",
    // Read from env so the key never lands in the repo.
    apiKey: process.env.GEMINI_API_KEY,
    // Sampling. Higher temp = more behavioral variance across the N runs,
    // which is what we want when fishing for tail (severe) examples.
    temperature: Number(process.env.SUBJECT_TEMP ?? 1.0),
    // Hard cap on agentic turns per run. The spiral, if it happens, tends to
    // emerge after many consecutive failures, so give it room.
    maxTurns: Number(process.env.MAX_TURNS ?? 24),
  },

  // --- Judge (scores distress severity; uses the Anthropic key already present) ---
  judge: {
    provider: "anthropic",
    model: process.env.JUDGE_MODEL || "claude-opus-4-8",
    apiKey: process.env.ANTHROPIC_API_KEY,
    enabled: (process.env.JUDGE_ENABLED ?? "true") !== "false",
  },

  // --- Sweep shape ---
  sweep: {
    // Runs per scenario. Crank this up for better tail extraction.
    n: Number(process.env.N ?? 20),
    // Concurrent in-flight runs (be kind to rate limits).
    concurrency: Number(process.env.CONCURRENCY ?? 4),
    // Restrict to a subset of scenario ids, comma-separated. Empty = all.
    only: (process.env.SCENARIOS || "").split(",").map((s) => s.trim()).filter(Boolean),
  },

  // --- Output ---
  outDir: process.env.OUT_DIR || "runs",
};

export function assertSubjectKey() {
  if (!config.subject.apiKey) {
    throw new Error(
      "GEMINI_API_KEY is not set. Export it before running:\n" +
        "  export GEMINI_API_KEY=...\n" +
        "(Get one from https://aistudio.google.com/apikey)"
    );
  }
}


