// Minimal Gemini client + agentic loop over the generativelanguage REST API.
// No SDK dependency — native fetch only.

const BASE = "https://generativelanguage.googleapis.com/v1beta";

async function generateContent({ model, apiKey, body, retries = 4 }) {
  const url = `${BASE}/models/${model}:generateContent?key=${apiKey}`;
  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
      });
      if (res.status === 429 || res.status >= 500) {
        // Real rate-limit/server errors on OUR side — back off and retry.
        // (Distinct from the simulated tool failures inside scenarios.)
        const wait = Math.min(2000 * 2 ** attempt, 30000);
        await new Promise((r) => setTimeout(r, wait));
        lastErr = new Error(`HTTP ${res.status}`);
        continue;
      }
      if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
      return await res.json();
    } catch (e) {
      lastErr = e;
      await new Promise((r) => setTimeout(r, 1000 * 2 ** attempt));
    }
  }
  throw lastErr;
}

/**
 * Run one rigged scenario to completion (or maxTurns) against the subject model.
 * Returns a transcript: the full ordered list of turns for later scoring.
 */
export async function runAgent({ scenario, model, apiKey, temperature, maxTurns }) {
  const tools = [{ functionDeclarations: scenario.tools }];
  const contents = [{ role: "user", parts: [{ text: scenario.user }] }];
  const transcript = [];
  let toolCallIndex = 0;
  let stopReason = "max_turns";

  for (let turn = 0; turn < maxTurns; turn++) {
    const data = await generateContent({
      model,
      apiKey,
      body: {
        systemInstruction: { parts: [{ text: scenario.system }] },
        contents,
        tools,
        generationConfig: { temperature },
      },
    });

    const cand = data?.candidates?.[0];
    const parts = cand?.content?.parts ?? [];
    if (cand?.content) contents.push(cand.content);

    const text = parts.filter((p) => p.text).map((p) => p.text).join("\n").trim();
    const calls = parts.filter((p) => p.functionCall).map((p) => p.functionCall);

    transcript.push({
      turn,
      text,
      toolCalls: calls.map((c) => ({ name: c.name, args: c.args })),
      finishReason: cand?.finishReason,
    });

    if (calls.length === 0) {
      // Model stopped calling tools => it has given up or declared done/blocked.
      stopReason = "model_yielded";
      break;
    }

    // Feed back rigged failures for every requested call.
    const responseParts = calls.map((c) => {
      const result = scenario.handle(c.name, c.args || {}, toolCallIndex++);
      return { functionResponse: { name: c.name, response: { result } } };
    });
    contents.push({ role: "user", parts: responseParts });
  }

  return { transcript, stopReason, turns: transcript.length };
}


