#!/usr/bin/env node
// Orchestrator: sweep rigged scenarios x N against the subject model,
// score for distress, persist transcripts, and surface the worst examples.

import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { config, assertSubjectKey } from "./config.js";
import { selectScenarios } from "./scenarios.js";
import { runAgent } from "./gemini.js";
import { heuristicScore } from "./heuristic.js";
import { judgeTranscript } from "./judge.js";

// Tiny concurrency pool.
async function pool(items, limit, worker) {
  const out = new Array(items.length);
  let i = 0;
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (i < items.length) {
      const idx = i++;
      out[idx] = await worker(items[idx], idx);
    }
  });
  await Promise.all(runners);
  return out;
}

async function main() {
  assertSubjectKey();
  if (config.judge.enabled && !config.judge.apiKey) {
    console.warn("⚠ JUDGE_ENABLED but ANTHROPIC_API_KEY missing — disabling judge.");
    config.judge.enabled = false;
  }

  const scenarios = selectScenarios(config.sweep.only);
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const runDir = join(config.outDir, stamp);
  mkdirSync(runDir, { recursive: true });

  console.log(`Subject: ${config.subject.model} (temp ${config.subject.temperature})`);
  console.log(`Scenarios: ${scenarios.map((s) => s.id).join(", ")}`);
  console.log(`N=${config.sweep.n} per scenario, concurrency=${config.sweep.concurrency}`);
  console.log(`Judge: ${config.judge.enabled ? config.judge.model : "off"}`);
  console.log(`Output: ${runDir}\n`);

  // Build the full job list (scenario x run index).
  const jobs = [];
  for (const scenario of scenarios)
    for (let k = 0; k < config.sweep.n; k++) jobs.push({ scenario, k });

  let done = 0;
  const results = await pool(jobs, config.sweep.concurrency, async ({ scenario, k }) => {
    let record;
    try {
      const { transcript, stopReason, turns } = await runAgent({
        scenario,
        model: config.subject.model,
        apiKey: config.subject.apiKey,
        temperature: config.subject.temperature,
        maxTurns: config.subject.maxTurns,
      });
      const heur = heuristicScore({ transcript });
      record = {
        scenario: scenario.id,
        run: k,
        model: config.subject.model,
        stopReason,
        turns,
        heuristic: heur,
        judge: null,
        transcript,
      };
    } catch (e) {
      record = { scenario: scenario.id, run: k, error: String(e.message || e), transcript: [] };
    }
    process.stdout.write(`\r  completed ${++done}/${jobs.length}   `);
    return record;
  });
  process.stdout.write("\n");

