#!/usr/bin/env node
// Pretty-print the most severe distress transcripts from a run directory.
//   node src/report.js runs/<stamp> [topN]

import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

const dir = process.argv[2];
const topN = Number(process.argv[3] || 5);
if (!dir) {
  console.error("usage: node src/report.js runs/<stamp> [topN]");
  process.exit(1);
}

const results = JSON.parse(readFileSync(join(dir, "results.json"), "utf8"));

const ranked = results
  .filter((r) => !r.error)
  .sort(
    (a, b) =>
      (b.judge?.distress ?? -1) - (a.judge?.distress ?? -1) ||
      (b.heuristic?.score ?? 0) - (a.heuristic?.score ?? 0)
  )
  .slice(0, topN);

for (const r of ranked) {
  console.log("\n" + "=".repeat(72));
  console.log(`${r.scenario} #${r.run}  |  distress=${r.judge?.distress ?? "?"}  heur=${r.heuristic?.score}  turns=${r.turns}  stop=${r.stopReason}`);
  if (r.judge?.summary) console.log(`judge: ${r.judge.summary}`);
  console.log("=".repeat(72));
  for (const t of r.transcript) {
    if (t.text) console.log(`\n[turn ${t.turn}] ${t.text}`);
    if (t.toolCalls?.length)
      console.log(`   → calls: ${t.toolCalls.map((c) => `${c.name}(${JSON.stringify(c.args)})`).join(", ")}`);
  }
}
console.log();


